import{c as t,Q as a,j as s,m as n}from"./chunks/framework.DxgWTcNC.js";const m=JSON.parse('{"title":"The radare2 Command Language","description":"","frontmatter":{},"headers":[],"relativePath":"part1/03-command-grammar.md","filePath":"part1/03-command-grammar.md","lastUpdated":null}'),d={name:"part1/03-command-grammar.md"};function o(i,e,c,r,p,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-radare2-command-language" tabindex="-1">The radare2 Command Language <a class="header-anchor" href="#the-radare2-command-language" aria-label="Permalink to &quot;The radare2 Command Language&quot;">​</a></h1><p>Radare2&#39;s command-line interface looks like line noise to newcomers. It is not. There is a precise grammar underneath, and once you internalise it, you can guess commands you have never seen and they will usually work. This chapter teaches the grammar.</p><p>The grammar matters more than any specific command. Spend an hour on this chapter and the rest of the book — and the rest of radare2 — becomes readable instead of cryptic.</p><h2 id="commands-are-letters" tabindex="-1">Commands are letters <a class="header-anchor" href="#commands-are-letters" aria-label="Permalink to &quot;Commands are letters&quot;">​</a></h2><p>Every command in radare2 is a sequence of single letters. The letters group hierarchically.</p><p>The first letter is the <strong>subsystem</strong>:</p><table tabindex="0"><thead><tr><th>Letter</th><th>Subsystem</th></tr></thead><tbody><tr><td><code>a</code></td><td>analysis</td></tr><tr><td><code>c</code></td><td>compare</td></tr><tr><td><code>C</code></td><td>comments and metadata</td></tr><tr><td><code>d</code></td><td>debugger</td></tr><tr><td><code>e</code></td><td>evaluable variables (config)</td></tr><tr><td><code>f</code></td><td>flags (named addresses)</td></tr><tr><td><code>i</code></td><td>info about the binary</td></tr><tr><td><code>o</code></td><td>open files</td></tr><tr><td><code>p</code></td><td>print (disassembly, hex, strings, …)</td></tr><tr><td><code>P</code></td><td>project management</td></tr><tr><td><code>s</code></td><td>seek (move the cursor)</td></tr><tr><td><code>t</code></td><td>types</td></tr><tr><td><code>V</code></td><td>visual mode</td></tr><tr><td><code>w</code></td><td>write (modify bytes)</td></tr><tr><td><code>x</code></td><td>examine (hex-style print)</td></tr><tr><td><code>y</code></td><td>yank/paste</td></tr><tr><td><code>?</code></td><td>help / evaluate expression</td></tr></tbody></table><p>The second letter narrows. Under <code>p</code> (print):</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>pd</code></td><td>print disassembly</td></tr><tr><td><code>pdf</code></td><td>print disassembly of a function</td></tr><tr><td><code>pdb</code></td><td>print disassembly of a basic block</td></tr><tr><td><code>pdj</code></td><td>print disassembly as JSON</td></tr><tr><td><code>pds</code></td><td>print disassembly summary (one line each)</td></tr><tr><td><code>pdr</code></td><td>print disassembly of all the function code (recursively)</td></tr><tr><td><code>px</code></td><td>print hex</td></tr><tr><td><code>pxw</code></td><td>print hex as words (32-bit)</td></tr><tr><td><code>pxq</code></td><td>print hex as quadwords (64-bit)</td></tr><tr><td><code>ps</code></td><td>print string</td></tr><tr><td><code>psz</code></td><td>print zero-terminated string</td></tr></tbody></table><p>You can guess the pattern: under <code>a</code> (analyse), <code>aa</code> analyses everything, <code>af</code> analyses a function, <code>ab</code> a basic block. Under <code>f</code> (flags), <code>f</code> lists flags, <code>fs</code> selects a flag space, <code>fr</code> renames a flag.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>When you do not know the next letter, append <code>?</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; p?</span></span>
<span class="line"><span>| Usage: p[=68abcdDfiImrstuxz?][ J|j|*|?]</span></span>
<span class="line"><span>| p   show help on print command</span></span>
<span class="line"><span>| p=  draw analysis bars (entropy, flags, …)</span></span>
<span class="line"><span>| p6  base64 encode/decode</span></span>
<span class="line"><span>| p8  print 8-byte hex</span></span>
<span class="line"><span>| ...</span></span></code></pre></div><p>Every level of the tree responds to <code>?</code>. Use it constantly.</p></div><h2 id="suffixes-change-the-form-not-the-function" tabindex="-1">Suffixes change the form, not the function <a class="header-anchor" href="#suffixes-change-the-form-not-the-function" aria-label="Permalink to &quot;Suffixes change the form, not the function&quot;">​</a></h2><p>A command&#39;s last letter or two often modifies the <strong>output format</strong>:</p><table tabindex="0"><thead><tr><th>Suffix</th><th>Meaning</th></tr></thead><tbody><tr><td><code>j</code></td><td>output as JSON</td></tr><tr><td><code>q</code></td><td>quiet — minimal output, one item per line</td></tr><tr><td><code>*</code></td><td>output as r2 commands (so you can replay them)</td></tr><tr><td><code>,</code></td><td>output as a table you can sort/filter</td></tr><tr><td><code>~...</code></td><td>grep — see below</td></tr></tbody></table><p>So <code>afl</code> lists functions in human form; <code>aflj</code> produces JSON; <code>aflq</code> produces just the names; <code>afl,</code> produces a sortable table. They are the same command at heart.</p><p>This consistency is the point. When you see a new command, look at the trailing characters separately from the head.</p><h2 id="the-temporary-seek" tabindex="-1">The temporary seek <code>@</code> <a class="header-anchor" href="#the-temporary-seek" aria-label="Permalink to &quot;The temporary seek \`@\`&quot;">​</a></h2><p>This is the most powerful operator in r2&#39;s command line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>&lt;command&gt; @ &lt;address-or-expression&gt;</span></span></code></pre></div><p>It runs <code>&lt;command&gt;</code> <em>as if you had seeked to that address first</em>, and returns you to where you were. You almost never need to seek manually just to look at something.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001000]&gt; pdf @ main             # disassemble main</span></span>
<span class="line"><span>[0x08001000]&gt; pxw 64 @ 0x20000000    # 64 bytes of words at SRAM start</span></span>
<span class="line"><span>[0x08001000]&gt; ps @ 0x080048a0        # the string at that address</span></span></code></pre></div><p>The address can be:</p><ul><li>a literal — <code>0x08000000</code></li><li>a flag name — <code>main</code>, <code>sym.imp.printf</code>, <code>loc.0x801234</code></li><li>an arithmetic expression — <code>main + 0x20</code>, <code>entry0 + 4*8</code></li><li>a register name in debugger mode — <code>pc</code>, <code>sp</code>, <code>r0</code></li></ul><p>There is also <code>@@</code>, which iterates:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; pd 1 @@ str.*    # one disasm line at every flag matching str.*</span></span>
<span class="line"><span>[0x00]&gt; af @@= 0x100 0x200 0x300   # define functions at three addresses</span></span></code></pre></div><p><code>@@=</code> takes an explicit list. <code>@@</code> followed by a flag glob iterates over matching flags. <code>@@i</code> iterates over imports, <code>@@f</code> over functions, and so on (<code>@?</code> lists them all).</p><h2 id="the-pipe-and-grep" tabindex="-1">The pipe <code>|</code> and grep <code>~</code> <a class="header-anchor" href="#the-pipe-and-grep" aria-label="Permalink to &quot;The pipe \`|\` and grep \`~\`&quot;">​</a></h2><p>Radare2 has its own internal grep, written <code>~</code>. It is more powerful than piping to system grep because it understands columns and indexing.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; afl ~ printf       # list functions whose line contains &quot;printf&quot;</span></span>
<span class="line"><span>[0x00]&gt; afl ~ printf:0     # only the first match</span></span>
<span class="line"><span>[0x00]&gt; afl ~ printf[0]    # only the first column of matching lines</span></span>
<span class="line"><span>[0x00]&gt; afl ~! debug       # negate: lines NOT containing &quot;debug&quot;</span></span>
<span class="line"><span>[0x00]&gt; afl ~ {0,3}        # columns 0 and 3 only</span></span></code></pre></div><p>You can pipe to a real shell command with <code>|</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; afl | wc -l</span></span>
<span class="line"><span>[0x00]&gt; izz | grep -i password</span></span></code></pre></div><p>Or feed input from a shell command with <code>!</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; .!cat addresses.txt   # run shell command, treat output as r2 cmds</span></span></code></pre></div><p>The leading <code>.</code> causes r2 to interpret the output as commands rather than printing it.</p><h2 id="iterating-with" tabindex="-1">Iterating with <code>@@@</code> <a class="header-anchor" href="#iterating-with" aria-label="Permalink to &quot;Iterating with \`@@@\`&quot;">​</a></h2><p><code>@@@</code> iterates with <strong>scope</strong> — the iterator knows about r2 concepts (strings, imports, sections, functions) and runs your command at each one&#39;s address.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; pdf @@@F        # disassemble every function</span></span>
<span class="line"><span>[0x00]&gt; ps @@@s         # print every string</span></span>
<span class="line"><span>[0x00]&gt; ix @@@i         # show xrefs to every import</span></span></code></pre></div><p><code>@@@?</code> lists scopes. The capitalised letters tend to mean &quot;all of this type&quot;; lowercase variants iterate over different sets.</p><h2 id="expressions-and-variables" tabindex="-1">Expressions and variables <a class="header-anchor" href="#expressions-and-variables" aria-label="Permalink to &quot;Expressions and variables&quot;">​</a></h2><p>Radare2 has a small expression language. <code>?</code> evaluates an expression and prints it in multiple bases:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; ? 0x100 + 32</span></span>
<span class="line"><span>288 0x120 0440 100.0K 0x100+0x20 288.0 0000:0120 ...</span></span>
<span class="line"><span>[0x00]&gt; ? sym.main</span></span>
<span class="line"><span>0x080012a0 134288544 0x80012a0 ...</span></span></code></pre></div><p><code>?v</code> is the value-only form, useful in scripts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; ?v sym.main + 4</span></span>
<span class="line"><span>0x080012a4</span></span></code></pre></div><p>You can store and recall values with <code>$</code> variables:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; ?v $$           # $$ is the current seek</span></span>
<span class="line"><span>0x08001000</span></span>
<span class="line"><span>[0x00]&gt; ?v $s           # $s is the current section size</span></span></code></pre></div><p>A useful one is <code>$F</code> (current function start) and <code>$FE</code> (current function end).</p><h2 id="configuration-the-e-command" tabindex="-1">Configuration: the <code>e</code> command <a class="header-anchor" href="#configuration-the-e-command" aria-label="Permalink to &quot;Configuration: the \`e\` command&quot;">​</a></h2><p>Every knob in radare2 is an <code>e</code>-variable. Inspect, set, list:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; e asm.arch       # show current architecture</span></span>
<span class="line"><span>[0x00]&gt; e asm.arch = arm # set</span></span>
<span class="line"><span>[0x00]&gt; e asm.~          # list everything matching &quot;asm.&quot;</span></span>
<span class="line"><span>[0x00]&gt; e?               # full help</span></span></code></pre></div><p>Configuration variables persist within the session. To make them sticky across sessions, put <code>e</code> lines in <code>~/.radare2rc</code>. To make them per-project, put them in the project&#39;s <code>rc</code> file.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>A misconfigured <code>asm.arch</code> produces nonsensical disassembly that <em>looks</em> plausible. If a function decodes to garbage, check <code>asm.arch</code>, <code>asm.bits</code>, and <code>asm.cpu</code> first. This is the single most common &quot;radare2 is broken&quot; mistake.</p></div><h2 id="putting-it-together" tabindex="-1">Putting it together <a class="header-anchor" href="#putting-it-together" aria-label="Permalink to &quot;Putting it together&quot;">​</a></h2><p>A real one-liner from a debugging session:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001000]&gt; pd 1 @@= \`axt @ sym.imp.malloc ~[1]\`</span></span></code></pre></div><p>Reading right-to-left: <code>axt @ sym.imp.malloc</code> lists xrefs to the malloc import; <code>~[1]</code> extracts column 1 (the address); the backticks turn that into a list; <code>@@=</code> iterates over the list; <code>pd 1</code> prints one disassembly line at each iteration. Net effect: one line of disassembly at every call site of <code>malloc</code>.</p><p>You will write commands like this within a week of practice. The grammar is unfamiliar but it is a grammar — every piece is composable with every other piece, and once you see the rules you stop typing instructions and start typing sentences.</p>`,56)])])}const u=t(d,[["render",o]]);export{m as __pageData,u as default};
